INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) SELECT 91723,0,0,0,0,0,0,0,0,'Well done, my friend. Let me try my calibrations again...',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID`=91723);
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) SELECT 91725,0,0,0,0,0,0,0,0,'Oh, that''s a relief! It looks like it''s all here. Thank you!',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID`=91725);
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) SELECT 92742,0,0,0,0,0,0,0,0,'Thank you. Let me see...',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID`=92742);
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) SELECT 92744,0,0,0,0,0,0,0,0,'I see... these gills appear to be healthy, for now. But we must not be complacent.',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID`=92744);
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) SELECT 92909,0,0,0,0,0,0,0,0,'Thanks a bunch! I''ll get to work on an escape plan. In the meantime, take this!',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID`=92909);
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) SELECT 96391,0,0,0,0,0,0,0,0,'Judging by this map, it certainly looks like these Dark Irons are planning some sort of incursion into the vaults beneath Ironforge. The band ye busted up to the east must be a scouting force.\r\n\r\nThank ye for bringing me this. If we hurry, we might be able to beat them to whatever their goal is down there.',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID`=96391);
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) SELECT 96393,0,0,0,0,0,0,0,0,'A Dark Iron incursion--right beneath our feet? Well, I''m relieved to hear that the Dark Iron commander has been dispatched.\r\n\r\nThe guards will head in and clean up the rest of the rabble. We''ll see to it that the breaches are sealed and the lower levels reinforced to ensure that no further incursions are possible.\r\n\r\nThank ye for yer service to Ironforge, $c. Take this as a small token of my gratitude. Oh, and if ye see that old Wildhammer rockhugger Farsen again, tell ''em to pay me a proper visit.',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID`=96393);
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) SELECT 97250,0,0,0,0,0,0,0,0,'So the rumors were true! I expected as much, tensions have been rising along the eastern coast for some time. I knew it would only be a matter of time before conflict crept into our territory.\r\n\r\nHowever, I am skeptical that we played a role in the tavern''s destruction. Too many Horde civilians rely on that route for trade and travel. Perhaps you could investigate further if you find the time.\r\n\r\nIn any case, today''s deed is a victory for the Horde, and a stern warning to the Alliance!',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID`=97250);
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) SELECT 97924,0,0,0,0,0,0,0,0,'There you have it, you can now craft your very own Camp Chair. Most folk don''t care much for camps being set up in the center of town, so you''ll need to head into the wilderness if you want to test it out.\r\n\r\nOh, and just remember, no camp is complete without a campfire. You''ll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven''t already, you might want to check in with someone who can train you in the culinary arts to learn the basics.',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID`=97924);
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) SELECT 98407,0,0,0,0,0,0,0,0,'Quite the armful you have.\r\n\r\nWhile this doesn''t solve our problem out here, I can rest comfortably knowing we''ve discouraged them pushing any further. Great work, $N.',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID`=98407);
INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) SELECT 97485,0,0,0,0,0,0,0,0,'You have done well.$B$BI thank you for taking the time to perform one of our time-honored traditions, $r. I hope that as you travel you will find plenty of occasions you wish to give thanks for.$B$BShould you ever wish to perform the ritual again, you should be able to repurchase the components I sent you to collect.$B$BGo with An''she''s warmth.',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` WHERE `ID`=97485);
